package app.nullvault;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import javax.crypto.AEADBadTagException;
public class VaultEngineTest {
 private JSONObject entry()throws Exception{return new JSONObject().put("title","Test").put("totp","GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ");}
 @Test public void rfc6238()throws Exception{long[] times={59,1111111109L,1111111111L,1234567890L,2000000000L,20000000000L};String[] codes={"287082","081804","050471","005924","279037","353130"};for(int i=0;i<times.length;i++)assertEquals(codes[i],VaultEngine.code(entry(),times[i]));}
 @Test public void encryptionRoundTripAndWrongKey()throws Exception{byte[] salt=VaultEngine.random(16),key=VaultEngine.derive("test password only".toCharArray(),salt);JSONArray items=new JSONArray().put(entry().put("password","test-secret"));JSONObject encrypted=VaultEngine.seal(items,key,salt);assertFalse(encrypted.toString().contains("test-secret"));assertEquals(items.toString(),VaultEngine.open(encrypted,key).toString());try{VaultEngine.open(encrypted,VaultEngine.random(32));fail("Wrong key accepted");}catch(AEADBadTagException expected){}}
 @Test public void rejectsTampering()throws Exception{byte[] key=VaultEngine.random(32);JSONObject e=VaultEngine.seal(new JSONArray().put(entry()),key,VaultEngine.random(16));byte[] data=java.util.Base64.getDecoder().decode(e.getString("data"));data[0]^=1;e.put("data",java.util.Base64.getEncoder().encodeToString(data));try{VaultEngine.open(e,key);fail("Tampering accepted");}catch(AEADBadTagException expected){}}
 @Test public void aegisImportAndDuplicates()throws Exception{String json="{\"db\":{\"entries\":[{\"type\":\"totp\",\"name\":\"alice\",\"issuer\":\"Example\",\"info\":{\"secret\":\"GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ\",\"algo\":\"SHA1\",\"digits\":6,\"period\":30}}]}}";JSONArray a=VaultEngine.parseImport(json);assertEquals("Example",a.getJSONObject(0).getString("title"));assertEquals(1,VaultEngine.merge(a,a).length());}
 @Test public void bitwardenImportPreservesOriginal()throws Exception{JSONArray a=VaultEngine.parseImport("{\"encrypted\":false,\"items\":[{\"name\":\"Site\",\"type\":1,\"login\":{\"username\":\"alice\",\"password\":\"pw\",\"totp\":\"GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ\"},\"fields\":[{\"name\":\"x\",\"value\":\"y\"}]}]}");assertEquals("pw",a.getJSONObject(0).getString("password"));assertTrue(a.getJSONObject(0).getJSONObject("sourceBitwarden").has("fields"));}
 @Test public void uriSettingsPreserved()throws Exception{JSONObject e=VaultEngine.fromUri("otpauth://totp/Example:alice?secret=GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ&algorithm=SHA256&digits=8&period=60");assertEquals("alice",e.getString("username"));assertEquals(60,e.getInt("period"));assertEquals("SHA256",e.getString("algorithm"));assertEquals(8,VaultEngine.code(e,59).length());}
 @Test public void unsupportedBitwardenFieldsArePreserved()throws Exception{JSONArray a=VaultEngine.parseImport("{\"items\":[{\"type\":3,\"name\":\"Card\",\"card\":{\"number\":\"test-number\"}}]}");assertEquals(1,a.length());assertTrue(a.getJSONObject(0).has("importWarning"));assertEquals("test-number",a.getJSONObject(0).getJSONObject("sourceBitwarden").getJSONObject("card").getString("number"));}
 @Test public void invalidTotpDoesNotBlockPasswords()throws Exception{JSONArray a=VaultEngine.parseImport("{\"encrypted\":false,\"items\":[{\"name\":\"Account\",\"type\":1,\"notes\":\"keep me\",\"login\":{\"username\":\"alice\",\"password\":\"keep-password\",\"totp\":\"steam://notbase32!\"}}]}");JSONObject e=a.getJSONObject(0);assertEquals("keep-password",e.getString("password"));assertEquals("keep me",e.getString("notes"));assertEquals("steam://notbase32!",e.getString("unsupportedOtp"));assertFalse(e.has("totp"));assertEquals(1,VaultEngine.merge(a,a).length());byte[] key=VaultEngine.random(32);JSONObject backup=VaultEngine.seal(a,key,VaultEngine.random(16));assertEquals("steam://notbase32!",VaultEngine.open(backup,key).getJSONObject(0).getString("unsupportedOtp"));}
 @Test public void emptyAndNullTotpDoNotFail()throws Exception{JSONArray a=VaultEngine.parseImport("{\"items\":[{\"name\":\"Null\",\"type\":1,\"login\":{\"totp\":null}},{\"name\":\"Empty\",\"type\":1,\"login\":{\"totp\":\"\"}}]}");assertEquals(2,a.length());assertFalse(a.getJSONObject(0).has("importWarning"));}
 @Test public void encryptedAegisStillRejected()throws Exception{try{VaultEngine.parseImport("{\"db\":\"encrypted\"}");fail("Encrypted Aegis accepted as plaintext");}catch(Exception expected){}}
 @Test public void importingDoesNotMutateOriginal()throws Exception{JSONArray original=new JSONArray().put(entry());JSONArray incoming=new JSONArray().put(entry().put("title","Other"));assertEquals(2,VaultEngine.merge(original,incoming).length());assertEquals(1,original.length());}
}
